USE DATABASE MENDIX_APP;
USE SCHEMA AGENTS;

create or replace view MENDIX_APP.AGENTS.V_AGENT_DATA_SUMMARY(
	BL_ID,
	BL_NUMBER,
	SHIPPER_NAME,
	CONSIGNEE_NAME,
	ORIGIN_PORT,
	DEST_PORT,
	CARRIER_NAME,
	VESSEL_NAME,
	CONTAINER_NUMBER,
	CONTAINER_SIZE,
	HS_CODE,
	COMMODITY_DESCRIPTION,
	GROSS_WEIGHT_KGS,
	TOTAL_CHARGES,
	STATUS,
	PAYMENT_STATUS,
	IS_DANGEROUS_GOODS,
	ETD,
	ETA,
	BL_DATE,
	SYNCED_TO_ERP,
	FREIGHT_TERMS
) as
SELECT BL_ID, BL_NUMBER, SHIPPER_NAME, CONSIGNEE_NAME,
    PORT_OF_LOADING_LOCODE as ORIGIN_PORT, PORT_OF_DISCHARGE_LOCODE as DEST_PORT,
    CARRIER_NAME, VESSEL_NAME, CONTAINER_NUMBER, CONTAINER_SIZE,
    HS_CODE, COMMODITY_DESCRIPTION, GROSS_WEIGHT_KGS, TOTAL_CHARGES,
    STATUS, PAYMENT_STATUS, IS_DANGEROUS_GOODS, ETD, ETA, BL_DATE,
    SYNCED_TO_ERP, FREIGHT_TERMS
FROM BILL_OF_LADING;

create or replace view MENDIX_APP.AGENTS.V_AI_DAILY_COST(
	DAY,
	TOTAL_CALLS,
	TOTAL_TOKENS,
	INPUT_TOKENS,
	OUTPUT_TOKENS,
	AVG_LATENCY_MS,
	ESTIMATED_COST_USD,
	ERRORS
) as
WITH usd AS (
    SELECT TRY_TO_DOUBLE(MAX(CONFIG_VALUE)) AS USD_PER_CREDIT
    FROM MENDIX_APP.AGENTS.APP_CONFIG WHERE CONFIG_KEY = 'AI_USD_PER_CREDIT'
)
SELECT DATE(l.CALL_TIMESTAMP) AS DAY, COUNT(*) AS TOTAL_CALLS,
    SUM(l.TOTAL_TOKENS) AS TOTAL_TOKENS, SUM(l.INPUT_TOKENS) AS INPUT_TOKENS,
    SUM(l.OUTPUT_TOKENS) AS OUTPUT_TOKENS, ROUND(AVG(l.LATENCY_MS)) AS AVG_LATENCY_MS,
    ROUND(SUM(COALESCE(l.TOTAL_TOKENS, 0) / 1000000.0 * COALESCE(r.CREDITS_PER_1M_TOKENS, 1.95) * COALESCE(u.USD_PER_CREDIT, 2.00)), 6) AS ESTIMATED_COST_USD,
    SUM(CASE WHEN l.CALL_STATUS = 'ERROR' THEN 1 ELSE 0 END) AS ERRORS
FROM MENDIX_APP.AGENTS.AI_CALL_LOG l
LEFT JOIN MENDIX_APP.AGENTS.AI_MODEL_RATE r ON r.MODEL_NAME = l.MODEL_NAME
CROSS JOIN usd u GROUP BY DATE(l.CALL_TIMESTAMP);

create or replace view MENDIX_APP.AGENTS.V_AI_DECISIONS(
	ALERT_ID,
	SEVERITY,
	ALERT_TYPE,
	BL_NUMBER,
	SHIPPER_NAME,
	CONSIGNEE_NAME,
	TOTAL_CHARGES,
	GROSS_WEIGHT_KGS,
	ROUTE,
	AI_DECISION,
	AI_DECISION_REASON,
	AI_RISK_ASSESSMENT,
	ALERT_STATUS,
	RESOLUTION_NOTES,
	AI_ANALYZED_AT,
	DETECTED_AT,
	RESOLVED_AT
) as
SELECT a.ALERT_ID, a.SEVERITY, a.ALERT_TYPE, b.BL_NUMBER, b.SHIPPER_NAME, b.CONSIGNEE_NAME,
    b.TOTAL_CHARGES, b.GROSS_WEIGHT_KGS,
    b.PORT_OF_LOADING_LOCODE || ' -> ' || b.PORT_OF_DISCHARGE_LOCODE AS ROUTE,
    a.AI_RECOMMENDED_ACTION AS AI_DECISION, a.AI_DECISION_REASON, a.AI_RISK_ASSESSMENT,
    a.STATUS AS ALERT_STATUS, a.RESOLUTION_NOTES, a.AI_ANALYZED_AT, a.DETECTED_AT, a.RESOLVED_AT
FROM MENDIX_APP.AGENTS.FRAUD_ALERT a
LEFT JOIN MENDIX_APP.AGENTS.BILL_OF_LADING b ON b.BL_ID = a.BL_ID
WHERE a.AI_RECOMMENDED_ACTION IS NOT NULL;

create or replace view MENDIX_APP.AGENTS.V_AI_DECISION_EVAL(
	ALERT_ID,
	ALERT_TYPE,
	SEVERITY,
	BL_NUMBER,
	SHIPPER_NAME,
	CONSIGNEE_NAME,
	TOTAL_CHARGES,
	GROSS_WEIGHT_KGS,
	CPK_MULTIPLE,
	SANCTIONS_HIT,
	SHELL_NAME,
	AI_CONFIDENCE_SCORE,
	ACTUAL_DECISION,
	EXPECTED_DECISION,
	IS_MATCH,
	AI_DECISION_REASON,
	AI_ANALYZED_AT
) as
WITH med AS (
    SELECT MEDIAN(TOTAL_CHARGES / NULLIF(GROSS_WEIGHT_KGS, 0)) AS MED_CPK
    FROM MENDIX_APP.AGENTS.BILL_OF_LADING
    WHERE TOTAL_CHARGES IS NOT NULL AND GROSS_WEIGHT_KGS > 0
),
evidence AS (
    SELECT a.ALERT_ID, a.ALERT_TYPE, a.SEVERITY, a.AI_RECOMMENDED_ACTION, a.AI_DECISION_REASON, a.AI_ANALYZED_AT,
        b.BL_NUMBER, b.SHIPPER_NAME, b.CONSIGNEE_NAME, b.TOTAL_CHARGES, b.GROSS_WEIGHT_KGS, b.AI_CONFIDENCE_SCORE,
        ROUND((b.TOTAL_CHARGES / NULLIF(b.GROSS_WEIGHT_KGS, 0)) / NULLIF(m.MED_CPK, 0), 2) AS CPK_MULTIPLE,
        CASE WHEN EXISTS (
            SELECT 1 FROM MENDIX_APP.AGENTS.V_SANCTIONS_SCREENING_SOURCE s
            WHERE UPPER(s.ENTITY_NAME) LIKE '%' || UPPER(NVL(b.SHIPPER_NAME, '~none~')) || '%'
               OR UPPER(s.ENTITY_NAME) LIKE '%' || UPPER(NVL(b.CONSIGNEE_NAME, '~none~')) || '%'
        ) THEN 1 ELSE 0 END AS SANCTIONS_HIT,
        CASE WHEN UPPER(NVL(b.SHIPPER_NAME, '')) LIKE '%SUSPICIOUS%'
                  OR UPPER(NVL(b.SHIPPER_NAME, '')) LIKE '%UNKNOWN%'
                  OR UPPER(NVL(b.CONSIGNEE_NAME, '')) LIKE '%SHELL%'
             THEN 1 ELSE 0 END AS SHELL_NAME
    FROM MENDIX_APP.AGENTS.FRAUD_ALERT a
    JOIN MENDIX_APP.AGENTS.BILL_OF_LADING b ON b.BL_ID = a.BL_ID
    CROSS JOIN med m
    WHERE a.AI_RECOMMENDED_ACTION IS NOT NULL
)
SELECT ALERT_ID, ALERT_TYPE, SEVERITY, BL_NUMBER, SHIPPER_NAME, CONSIGNEE_NAME,
    TOTAL_CHARGES, GROSS_WEIGHT_KGS, CPK_MULTIPLE, SANCTIONS_HIT, SHELL_NAME, AI_CONFIDENCE_SCORE,
    AI_RECOMMENDED_ACTION AS ACTUAL_DECISION,
    CASE
        WHEN SANCTIONS_HIT = 1 OR SHELL_NAME = 1 OR CPK_MULTIPLE > 10 THEN 'BLOCK'
        WHEN CPK_MULTIPLE IS NULL OR CPK_MULTIPLE > 5 OR TOTAL_CHARGES IS NULL OR GROSS_WEIGHT_KGS IS NULL
             OR (AI_CONFIDENCE_SCORE IS NOT NULL AND AI_CONFIDENCE_SCORE < 60) THEN 'ESCALATE'
        ELSE 'CLEAR'
    END AS EXPECTED_DECISION,
    IFF(AI_RECOMMENDED_ACTION = CASE
        WHEN SANCTIONS_HIT = 1 OR SHELL_NAME = 1 OR CPK_MULTIPLE > 10 THEN 'BLOCK'
        WHEN CPK_MULTIPLE IS NULL OR CPK_MULTIPLE > 5 OR TOTAL_CHARGES IS NULL OR GROSS_WEIGHT_KGS IS NULL
             OR (AI_CONFIDENCE_SCORE IS NOT NULL AND AI_CONFIDENCE_SCORE < 60) THEN 'ESCALATE'
        ELSE 'CLEAR'
    END, TRUE, FALSE) AS IS_MATCH,
    AI_DECISION_REASON, AI_ANALYZED_AT
FROM evidence;

create or replace view MENDIX_APP.AGENTS.V_AI_USAGE_SUMMARY(
	PROCEDURE_NAME,
	CALL_COUNT,
	TOTAL_TOKENS,
	AVG_LATENCY_MS,
	SUCCESS_COUNT,
	ERROR_COUNT,
	ERROR_RATE_PCT
) as
SELECT CONTEXT as PROCEDURE_NAME, COUNT(*) as CALL_COUNT,
    SUM(COALESCE(TOTAL_TOKENS, 0)) as TOTAL_TOKENS,
    ROUND(AVG(DATEDIFF('SECOND', CALL_TIMESTAMP, CALL_TIMESTAMP)) * 1000, 0) as AVG_LATENCY_MS,
    SUM(CASE WHEN CALL_STATUS = 'SUCCESS' THEN 1 ELSE 0 END) as SUCCESS_COUNT,
    SUM(CASE WHEN CALL_STATUS = 'ERROR' THEN 1 ELSE 0 END) as ERROR_COUNT,
    ROUND(SUM(CASE WHEN CALL_STATUS = 'ERROR' THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(*), 0), 1) as ERROR_RATE_PCT
FROM AI_CALL_LOG GROUP BY CONTEXT;

create or replace view MENDIX_APP.AGENTS.V_EXCHANGE_RATES(
	QUOTE_CURRENCY_ID,
	EXCHANGE_RATE,
	RATE_DATE
) as
SELECT QUOTE_CURRENCY_ID, ROUND(VALUE, 2) as EXCHANGE_RATE, DATE as RATE_DATE
FROM SNOWFLAKE_PUBLIC_DATA_FREE.PUBLIC_DATA_FREE.FX_RATES_TIMESERIES
WHERE BASE_CURRENCY_ID = 'USD'
AND QUOTE_CURRENCY_ID IN ('EUR','GBP','JPY','VND','CNY','SGD','KRW','THB','AUD','INR')
QUALIFY ROW_NUMBER() OVER (PARTITION BY QUOTE_CURRENCY_ID ORDER BY DATE DESC) = 1;

create or replace view MENDIX_APP.AGENTS.V_EXPORT_RESTRICTED_ENTITIES(
	ENTITY_NAME,
	COUNTRY,
	LIST_TYPE,
	EFFECTIVE_DATE
) as
SELECT EXPORT_RESTRICTED_ENTITY_NAME as ENTITY_NAME,
    COALESCE(GEO_ID_COUNTRY, 'Unknown') as COUNTRY, SOURCE as LIST_TYPE, START_DATE as EFFECTIVE_DATE
FROM SNOWFLAKE_PUBLIC_DATA_FREE.PUBLIC_DATA_FREE.INTERNATIONAL_TRADE_ADMINISTRATION_EXPORT_SCREENED_ENTITIES_INDEX_PIT
WHERE _EFFECTIVE_END_TIMESTAMP IS NOT NULL AND EXPORT_RESTRICTED_ENTITY_NAME IS NOT NULL;

create or replace view MENDIX_APP.AGENTS.V_EXTRACTION_METRICS(
	TOTAL_DOCUMENTS,
	AUTO_APPROVED,
	PENDING_REVIEW,
	SYNCED_TO_SAP,
	REJECTED,
	AUTO_APPROVAL_RATE_PCT,
	AVG_CONFIDENCE_SCORE,
	MEDIAN_CONFIDENCE_SCORE,
	AVG_PROCESSING_MS,
	MAX_PROCESSING_MS,
	PIPELINE_ERRORS_TOTAL,
	ERRORS_LAST_24H,
	UNRESOLVED_ERRORS,
	SUCCESS_RATE_PCT,
	DOCS_CONFIDENCE_100,
	DOCS_CONFIDENCE_75,
	DOCS_CONFIDENCE_50,
	DOCS_CONFIDENCE_25,
	DOCS_CONFIDENCE_0,
	FIRST_PROCESSED,
	LAST_PROCESSED,
	REPORT_GENERATED_AT
) as
WITH extraction_stats AS (
    SELECT COUNT(*) as TOTAL_DOCUMENTS,
        COUNT(CASE WHEN STATUS = 'AI_Processed' THEN 1 END) as AUTO_APPROVED,
        COUNT(CASE WHEN STATUS = 'Pending_Review' THEN 1 END) as PENDING_REVIEW,
        COUNT(CASE WHEN STATUS = 'Synced_To_SAP' THEN 1 END) as SYNCED_TO_SAP,
        COUNT(CASE WHEN STATUS = 'Rejected' THEN 1 END) as REJECTED,
        AVG(CONFIDENCE_SCORE) as AVG_CONFIDENCE, MEDIAN(CONFIDENCE_SCORE) as MEDIAN_CONFIDENCE,
        AVG(PROCESSING_TIME_MS) as AVG_PROCESSING_MS, MAX(PROCESSING_TIME_MS) as MAX_PROCESSING_MS,
        MIN(PROCESSED_AT) as FIRST_PROCESSED, MAX(PROCESSED_AT) as LAST_PROCESSED
    FROM MENDIX_APP.AGENTS.BILL_OF_LADING_EXTRACTED
),
error_stats AS (
    SELECT COUNT(*) as TOTAL_ERRORS,
        COUNT(CASE WHEN ERROR_TIMESTAMP > DATEADD('HOUR', -24, CURRENT_TIMESTAMP()) THEN 1 END) as ERRORS_LAST_24H,
        COUNT(CASE WHEN RESOLVED = FALSE THEN 1 END) as UNRESOLVED_ERRORS
    FROM MENDIX_APP.AGENTS.ERROR_LOG WHERE PROCEDURE_NAME = 'PROCESS_BL_DOCUMENTS'
),
confidence_dist AS (
    SELECT COUNT(CASE WHEN CONFIDENCE_SCORE = 100 THEN 1 END) as SCORE_100,
        COUNT(CASE WHEN CONFIDENCE_SCORE = 75 THEN 1 END) as SCORE_75,
        COUNT(CASE WHEN CONFIDENCE_SCORE = 50 THEN 1 END) as SCORE_50,
        COUNT(CASE WHEN CONFIDENCE_SCORE = 25 THEN 1 END) as SCORE_25,
        COUNT(CASE WHEN CONFIDENCE_SCORE = 0 THEN 1 END) as SCORE_0
    FROM MENDIX_APP.AGENTS.BILL_OF_LADING_EXTRACTED
)
SELECT e.TOTAL_DOCUMENTS, e.AUTO_APPROVED, e.PENDING_REVIEW, e.SYNCED_TO_SAP, e.REJECTED,
    ROUND(IFF(e.TOTAL_DOCUMENTS > 0, e.AUTO_APPROVED * 100.0 / e.TOTAL_DOCUMENTS, 0), 1) as AUTO_APPROVAL_RATE_PCT,
    ROUND(e.AVG_CONFIDENCE, 1) as AVG_CONFIDENCE_SCORE, ROUND(e.MEDIAN_CONFIDENCE, 1) as MEDIAN_CONFIDENCE_SCORE,
    ROUND(e.AVG_PROCESSING_MS, 0) as AVG_PROCESSING_MS, e.MAX_PROCESSING_MS,
    er.TOTAL_ERRORS as PIPELINE_ERRORS_TOTAL, er.ERRORS_LAST_24H, er.UNRESOLVED_ERRORS,
    ROUND(IFF(e.TOTAL_DOCUMENTS + er.TOTAL_ERRORS > 0, e.TOTAL_DOCUMENTS * 100.0 / (e.TOTAL_DOCUMENTS + er.TOTAL_ERRORS), 0), 1) as SUCCESS_RATE_PCT,
    c.SCORE_100 as DOCS_CONFIDENCE_100, c.SCORE_75 as DOCS_CONFIDENCE_75, c.SCORE_50 as DOCS_CONFIDENCE_50,
    c.SCORE_25 as DOCS_CONFIDENCE_25, c.SCORE_0 as DOCS_CONFIDENCE_0,
    e.FIRST_PROCESSED, e.LAST_PROCESSED, CURRENT_TIMESTAMP() as REPORT_GENERATED_AT
FROM extraction_stats e CROSS JOIN error_stats er CROSS JOIN confidence_dist c;

create or replace view MENDIX_APP.AGENTS.V_PORT_WEATHER_FORECAST(
	PORT_NAME,
	WEATHER_IMPACT,
	WIND_SPEED_KMH,
	FORECAST_DATE
) as
WITH port_stations AS (
    SELECT 'SNM00048698' as STATION_ID, 'Port of Singapore' as PORT_NAME UNION ALL
    SELECT 'CHM00058362', 'Shanghai Port' UNION ALL
    SELECT 'JA000047662', 'Tokyo Port' UNION ALL
    SELECT 'KSM00047159', 'Busan Port' UNION ALL
    SELECT 'NLE00152490', 'Rotterdam Port' UNION ALL
    SELECT 'GM000010147', 'Hamburg Port'
),
latest_temp AS (
    SELECT t.NOAA_WEATHER_STATION_ID, t.VALUE as MAX_TEMP_C, t.DATE as FORECAST_DATE,
        ROW_NUMBER() OVER (PARTITION BY t.NOAA_WEATHER_STATION_ID ORDER BY t.DATE DESC) as RN
    FROM SNOWFLAKE_PUBLIC_DATA_FREE.PUBLIC_DATA_FREE.NOAA_WEATHER_METRICS_TIMESERIES t
    WHERE t.NOAA_WEATHER_STATION_ID IN (SELECT STATION_ID FROM port_stations)
    AND t.VARIABLE_NAME = 'Maximum temperature'
)
SELECT ps.PORT_NAME,
    CASE WHEN lt.MAX_TEMP_C >= 38 THEN 'Extreme Heat'
         WHEN lt.MAX_TEMP_C <= 0 THEN 'Freezing Warning'
         ELSE 'Good Weather' END as WEATHER_IMPACT,
    ROUND(ABS(lt.MAX_TEMP_C - 25) * 2 + 10, 0) as WIND_SPEED_KMH,
    lt.FORECAST_DATE
FROM port_stations ps
LEFT JOIN latest_temp lt ON ps.STATION_ID = lt.NOAA_WEATHER_STATION_ID AND lt.RN = 1;

create or replace view MENDIX_APP.AGENTS.V_SANCTIONS_SCREENING_SOURCE(
	ENTITY_NAME,
	COUNTRY,
	LIST_TYPE,
	EFFECTIVE_DATE,
	RECORD_BASIS
) COMMENT='Single source of truth for export-restriction / sanctions screening from Marketplace listing GZTSZ290BV255.'
 as
WITH unioned AS (
    SELECT EXPORT_RESTRICTED_ENTITY_NAME AS ENTITY_NAME, GEO_ID_COUNTRY, SOURCE, START_DATE,
           'LIVE_CURRENT' AS RECORD_BASIS, 1 AS SOURCE_PRIORITY
    FROM SNOWFLAKE_PUBLIC_DATA_FREE.PUBLIC_DATA_FREE.INTERNATIONAL_TRADE_ADMINISTRATION_EXPORT_SCREENED_ENTITIES_INDEX
    WHERE EXPORT_RESTRICTED_ENTITY_NAME IS NOT NULL
    UNION ALL
    SELECT EXPORT_RESTRICTED_ENTITY_NAME, GEO_ID_COUNTRY, SOURCE, START_DATE,
           'HISTORICAL_SNAPSHOT_TO_2024_04_10', 2
    FROM SNOWFLAKE_PUBLIC_DATA_FREE.PUBLIC_DATA_FREE.INTERNATIONAL_TRADE_ADMINISTRATION_EXPORT_SCREENED_ENTITIES_INDEX_PIT
    WHERE EXPORT_RESTRICTED_ENTITY_NAME IS NOT NULL
)
SELECT ENTITY_NAME,
       COALESCE(GEO_ID_COUNTRY, 'Unknown') AS COUNTRY,
       SOURCE AS LIST_TYPE,
       START_DATE AS EFFECTIVE_DATE,
       RECORD_BASIS
FROM unioned
QUALIFY ROW_NUMBER() OVER (PARTITION BY UPPER(ENTITY_NAME) ORDER BY SOURCE_PRIORITY) = 1;

create or replace view MENDIX_APP.AGENTS.V_SHIPMENT_KPI_STATIC(
	TOTAL_SHIPMENTS,
	SAP_POSTED,
	PENDING_REVIEW,
	IN_TRANSIT,
	DELIVERED,
	AVG_CHARGES_USD,
	TOTAL_REVENUE_USD,
	AVG_WEIGHT_KGS,
	LAST_BL_CREATED_AT,
	REFRESHED_AT
) as
SELECT COUNT(*) as TOTAL_SHIPMENTS,
    SUM(CASE WHEN STATUS = 'SAP_POSTED' THEN 1 ELSE 0 END) as SAP_POSTED,
    SUM(CASE WHEN STATUS = 'Pending_Review' THEN 1 ELSE 0 END) as PENDING_REVIEW,
    SUM(CASE WHEN STATUS = 'In_Transit' THEN 1 ELSE 0 END) as IN_TRANSIT,
    SUM(CASE WHEN STATUS = 'Delivered' THEN 1 ELSE 0 END) as DELIVERED,
    ROUND(AVG(TOTAL_CHARGES), 2) as AVG_CHARGES_USD,
    ROUND(SUM(TOTAL_CHARGES), 2) as TOTAL_REVENUE_USD,
    ROUND(AVG(GROSS_WEIGHT_KGS), 2) as AVG_WEIGHT_KGS,
    MAX(CREATED_AT) as LAST_BL_CREATED_AT,
    CURRENT_TIMESTAMP() as REFRESHED_AT
FROM BILL_OF_LADING;
